// C implementation of vstodo cmdWorktree header
//\n// NOTE: This is a skeleton implementation for migration purposes.\n// It follows the Go cmd_worktree.go command interface.\n//\n// This file cannot be compiled/verified locally per AGENTS.md constraints\n// (no C compiler available). It is provided as the intended C replacement\n// for cmd_worktree.go.\n\n#ifndef VSTODO_C_CMD_WORKTREE_H\n#define VSTODO_C_CMD_WORKTREE_H\n\n// Manage multiple working trees.\n// Equivalent to Go cmdWorktree function.\n// app — vstodo application context pointer\n// args — worktree commands (list, add <path>, remove <path>)\n// arg_count — number of arguments\n//\n// Returns 0 on success, negative error code on failure.\nint cmd_worktree(void *app, const char **args, int arg_count);\n\n#endif // VSTODO_C_CMD_WORKTREE_H